$ cat ~/bin/kopia-katalogu.sh
#!/bin/bash
# kopia-katalogu.sh [-n] [-v] [-e WZORZEC]... [-b KB/s] ZRODLO CEL
set -euo pipefail
uzycie() { echo "Uzycie: ${0##*/} [-n] [-v] [-e WZORZEC]... [-b KB/s] ZRODLO CEL" >&2; }
opcje=(-a); wykluczenia=()
while getopts ":nve:b:h" opt; do
    case "$opt" in
        n) opcje+=(-n -i) ;;
        v) opcje+=(-v) ;;
        e) wykluczenia+=("--exclude=$OPTARG") ;;
        b) [[ $OPTARG =~ ^[0-9]+$ ]] || { echo "BLAD: -b wymaga liczby KB/s" >&2; exit 2; }
           opcje+=("--bwlimit=$OPTARG") ;;
        h) uzycie; exit 0 ;;
        :) echo "BLAD: opcja -$OPTARG wymaga wartosci" >&2; uzycie; exit 2 ;;
        \?) echo "BLAD: nieznana opcja -$OPTARG" >&2; uzycie; exit 2 ;;
    esac
done
shift $((OPTIND - 1))
(( $# == 2 )) || { echo "BLAD: potrzebne ZRODLO i CEL" >&2; uzycie; exit 2; }
rsync "${opcje[@]}" "${wykluczenia[@]}" -- "${1%/}/" "$2"
